/**
 * drills.ts - high-repetition practice.
 *
 * Playing full hands is the fun part, but it's a slow way to learn. A hand
 * takes a minute and contains maybe three decisions, most of them easy. A drill
 * gives you the hard decision on its own, over and over, so you get two hundred
 * repetitions in the time a table session would give you twenty.
 *
 * Every spot is generated by dealing a real hand at a real table and playing it
 * forward until the situation we want appears. Inventing a board out of thin
 * air would be faster, but the pot sizes, the positions and the betting would
 * not hang together the way they do in a real hand - and learning from spots
 * that could never actually occur is worse than not practising at all.
 */

import type { Card } from './cards';
import { makeRng, shuffle, makeDeck } from './cards';
import { newHand, applyAction, toCall } from './engine';
import type { HandState } from './engine';
import { getPersona, botAction, tableLineup } from './bots';
import { newRangeBook, updateBookForAction, pruneBook } from './ranges';
import type { RangeBook } from './ranges';
import type { Lineup } from './grade';
import { exactEquity, fastEquity, findOuts } from './equity';
import { evaluate } from './evaluator';

export type DrillId = 'preflop' | 'potodds' | 'outs' | 'equity';

export interface DrillMeta {
  id: DrillId;
  name: string;
  blurb: string;
  teaches: string;
}

export const DRILLS: DrillMeta[] = [
  {
    id: 'preflop',
    name: 'Play or fold',
    blurb: 'Two cards, a seat, and a decision.',
    teaches:
      'Which starting hands are worth playing, and from which seat. Most losing players lose most ' +
      'of their money before the flop by playing too many hands from too early a position, which ' +
      'makes this the highest-value drill there is.',
  },
  {
    id: 'potodds',
    name: 'Price check',
    blurb: 'Someone bet at you. Is calling worth it?',
    teaches:
      'Weighing what you must pay against how often you win. Once this is automatic you stop making ' +
      'the two commonest errors at once - calling too wide, and folding when you are being offered a bargain.',
  },
  {
    id: 'outs',
    name: 'Count the outs',
    blurb: 'You are behind. How many cards save you?',
    teaches:
      'Counting outs, including the traps. A card that completes your flush while pairing the board ' +
      'can hand your opponent a full house, and it does not count.',
  },
  {
    id: 'equity',
    name: 'Guess the odds',
    blurb: 'Two hands face up. What are your chances?',
    teaches:
      'Calibrating instinct against the real numbers. Most people are badly wrong about how often a ' +
      'big pair beats two overcards, and about what a draw is really worth.',
  },
];

export interface PlaySpot {
  kind: 'preflop' | 'potodds';
  state: HandState;
  heroSeat: number;
  lineup: Lineup;
  book: RangeBook;
}

export interface OutsSpot {
  kind: 'outs';
  hero: Card[];
  villain: Card[];
  board: Card[];
  outs: Card[];
  equity: number;
}

export interface EquitySpot {
  kind: 'equity';
  hero: Card[];
  villain: Card[];
  board: Card[];
  equity: number;
}

export type DrillSpot = PlaySpot | OutsSpot | EquitySpot;

/**
 * Deal hands at a real table until we land in the kind of spot this drill is
 * about, tracking every opponent's range along the way so the grader has
 * something to work with the moment we stop.
 */
function dealUntilSpot(
  seed: number,
  playerCount: number,
  accept: (s: HandState, heroSeat: number) => boolean,
  maxAttempts = 300
): PlaySpot | null {
  const rng = makeRng(seed);

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    const heroSeat = Math.floor(rng() * playerCount);
    const ids = tableLineup(playerCount, heroSeat);
    const lineup: Lineup = ids.map((id) => (id === 'hero' ? null : getPersona(id)));

    let state = newHand({
      playerCount,
      startingStack: 200,
      button: attempt % playerCount,
      bigBlind: 2,
      seed: Math.floor(rng() * 2 ** 31),
    });
    let book = newRangeBook(state, heroSeat);

    let guard = 0;
    while (!state.complete && guard++ < 60) {
      const seat = state.toAct;
      if (seat === heroSeat) {
        if (accept(state, heroSeat)) {
          return {
            kind: state.street === 0 ? 'preflop' : 'potodds',
            state, heroSeat, lineup, book,
          };
        }
        // Not the spot we want, so keep the hand moving with sensible play.
        state = applyAction(state, botAction(state, getPersona('tag'), rng));
      } else {
        const persona = lineup[seat]!;
        const before = state;
        const action = botAction(state, persona, rng);
        book = updateBookForAction(book, before, persona, action, seat);
        state = applyAction(state, action);
      }
      book = pruneBook(book, [...state.hole[heroSeat], ...state.board]);
    }
  }
  return null;
}

export function makePreflopSpot(seed: number, playerCount = 6): PlaySpot | null {
  return dealUntilSpot(seed, playerCount, (s) => s.street === 0);
}

export function makePotOddsSpot(seed: number, playerCount = 6): PlaySpot | null {
  return dealUntilSpot(seed, playerCount, (s, hero) => s.street >= 1 && toCall(s, hero) > 0);
}

/**
 * A spot where the hero is currently losing but can still get there.
 *
 * We deal at random and keep only hands where you're behind with between two
 * and fifteen outs - the band where counting them actually changes what you do.
 */
export function makeOutsSpot(seed: number): OutsSpot | null {
  const rng = makeRng(seed);
  for (let attempt = 0; attempt < 600; attempt++) {
    const deck = shuffle(makeDeck(), rng);
    const hero = [deck[0], deck[1]];
    const villain = [deck[2], deck[3]];
    const boardLength = rng() < 0.65 ? 3 : 4;
    const board = deck.slice(4, 4 + boardLength);

    if (evaluate([...hero, ...board]) >= evaluate([...villain, ...board])) continue;
    const outs = findOuts(hero, villain, board);
    if (outs.length < 2 || outs.length > 15) continue;

    return { kind: 'outs', hero, villain, board, outs, equity: exactEquity(hero, villain, board).equity };
  }
  return null;
}

export function makeEquitySpot(seed: number): EquitySpot {
  const rng = makeRng(seed);
  const deck = shuffle(makeDeck(), rng);
  const hero = [deck[0], deck[1]];
  const villain = [deck[2], deck[3]];
  const r = rng();
  const boardLength = r < 0.4 ? 0 : r < 0.75 ? 3 : 4;
  const board = deck.slice(4, 4 + boardLength);
  // fastEquity enumerates exactly once there's a flop and samples before it.
  // Exact preflop means 1.7 million runouts and a visible pause, for an answer
  // finer than anyone's guess in this drill.
  return { kind: 'equity', hero, villain, board, equity: fastEquity(hero, villain, board).equity };
}

export function makeSpot(drill: DrillId, seed: number, playerCount = 6): DrillSpot | null {
  switch (drill) {
    case 'preflop': return makePreflopSpot(seed, playerCount);
    case 'potodds': return makePotOddsSpot(seed, playerCount);
    case 'outs': return makeOutsSpot(seed);
    case 'equity': return makeEquitySpot(seed);
  }
}

/** Scoring for the numeric drills, where "close" deserves partial credit. */
export function scoreGuess(guess: number, truth: number, tolerance: number): {
  correct: boolean; close: boolean; error: number;
} {
  const error = Math.abs(guess - truth);
  return { correct: error <= tolerance, close: error <= tolerance * 2.5, error };
}
